export function getQuizzesByModule(moduleNumber) {
  const modNum = Number(moduleNumber);
  return FALLBACK_QUIZZES.filter(q => Number(q.moduleNumber) === modNum);
}

export function getQuizzesByTopic(topicSlug) {
  return FALLBACK_QUIZZES.filter(q => q.topicSlug === topicSlug);
}
